[
  {
    "id": 1,
    "name": "Broken Access Control",
    "definition": "Restrictions on what authenticated users are allowed to do are not properly enforced, allowing attackers to access unauthorized resources or perform actions they are not permitted to perform."
  },
  {
    "id": 2,
    "name": "Cryptographic Failures",
    "definition": "Sensitive data is not properly protected due to weak encryption algorithms, missing encryption, or improper handling of cryptographic keys, leading to data exposure."
  },
  {
    "id": 3,
    "name": "Injection",
    "definition": "Untrusted data is sent to an interpreter as part of a command or query, such as SQL, OS commands, or LDAP, allowing attackers to execute arbitrary code or manipulate data."
  },
  {
    "id": 4,
    "name": "Insecure Design",
    "definition": "The application lacks sufficient security controls or relies on flawed design patterns, making it vulnerable to attacks even if other security measures are implemented correctly."
  },
  {
    "id": 5,
    "name": "Security Misconfiguration",
    "definition": "Security settings are not properly configured, default credentials are left in place, or unnecessary features are enabled, creating exploitable weaknesses."
  },
  {
    "id": 6,
    "name": "Vulnerable and Outdated Components",
    "definition": "The use of libraries, frameworks, or other software modules with known vulnerabilities that are not updated or patched, allowing attackers to exploit known flaws."
  },
  {
    "id": 7,
    "name": "Identification and Authentication Failures",
    "definition": "Mechanisms for verifying user identity are weak or broken, such as allowing weak passwords, lacking multi-factor authentication, or having insecure session management."
  },
  {
    "id": 8,
    "name": "Software and Data Integrity Failures",
    "definition": "The application does not properly validate the integrity of updates, plugins, or data inputs, allowing attackers to inject malicious code or manipulate data."
  },
  {
    "id": 9,
    "name": "Security Logging and Monitoring Failures",
    "definition": "Inadequate logging and monitoring of security events, preventing the detection and response to attacks in a timely manner."
  },
  {
    "id": 10,
    "name": "Server-Side Request Forgery (SSRF)",
    "definition": "An attacker induces the server to make requests to an internal resource that would otherwise be inaccessible, potentially exposing internal services or metadata."
  }
]
